import time

from django.conf import settings
from django.core.management.base import BaseCommand
from django.db import models
from django.utils.translation import gettext_lazy as _

class Command(BaseCommand):
    help = _('Setup a DnD game.')

    def add_arguments(self, parser):
        parser.add_argument('--settings', type=str,
                            help='The settings file.')
        parser.add_argument('--game', type=str,
                            help='The game name.')
        parser.add_argument('--name', type=str,
                            help='The name of the game.')
        parser.add_argument('--level', type=str,
                            help='The level of the game.')
        parser.add_argument('--experience', type=int,
                            help='The experience of the player.')
        parser.add_argument('--health', type=int,
                            help='The health of the player.')
        parser.add_argument('--stats', type=dict,
                            help='The stats of the player.')

        return parser.parse_args()

    def handle(self, *args, **options):
        self.run_command(options)

    def run_command(self, command):
        if command == 'setup':
            self.add_arguments(command)
            self.add_arguments(command)
            self.run_command(command)

    def run_command(self, command):
        settings = get_settings()
        game = get_game(settings)
        self.add_game(game)
        self.add_settings(settings)
        self.add_stats(settings)
        self.add_level(settings)
        self.add_experience(settings)
        self.add_health(settings)
        self.add_stats(settings)

        self.run_command(command)
